seeds = [(0, 4), (2, 8), (5, 8), (14, 3)]

for c, val in enumerate(content):
    grid[10][5 + c] = val

print("Trying: copy_r = sr + sc + 2, copy_c = sc + 2 + c")
for sr, sc in seeds:
    for c, val in enumerate(content):
        copy_r = sr + sc + 2
        copy_c = sc + 2 + c
        if 0 <= copy_r < 22 and 0 <= copy_c < 12:
            grid[copy_r][copy_c] = val

for r in range(22):
    if any(grid[r][c] != 8 for c in range(12)):
        print(f"{r}: " + " ".join(str(grid[r][c]) for c in range(12)))
print(f"Non-bg: {np.count_nonzero(grid != 8)}")

answer = {"action": "submit", "grid": grid.tolist()}
print(json.dumps(answer))

